function inspect(raw){const t=raw.content.filter(c=>c.type==="text").map(c=>c.text).join("\n");const rows=[...t.matchAll(/^\s*([1-9])\s+([XO.](?:\s+[XO.]){8})\s+\1\s*$/gm)];if(rows.length!==9)throw Error("board missing");const b=Array(81).fill(".");for(const r of rows)r[2].split(/\s+/).forEach((v,x)=>b[(9-Number(r[1]))*9+x]=v);const name=i=>"ABCDEFGHJ"[i%9]+(9-Math.floor(i/9));const adj=i=>[i%9?i-1:-1,i%9<8?i+1:-1,i>=9?i-9:-1,i<72?i+9:-1].filter(j=>j>=0);const seen=new Set(),groups=[],regions=[];for(let i=0;i<81;i++){if(seen.has(i))continue;let todo=[i],p=[],edge=new Set(),libs=new Set();seen.add(i);while(todo.length){const k=todo.pop();p.push(k);for(const j of adj(k)){if(b[j]===b[i]&&!seen.has(j)){seen.add(j);todo.push(j)}else if(b[j]!==b[i]){edge.add(b[j]);if(b[j]===".")libs.add(j)}}}if(b[i]===".")regions.push({points:p.map(name).sort(),boundary:[...edge].sort()});else groups.push({color:b[i],stones:p.map(name).sort(),liberties:[...libs].map(name).sort()})}const area={X:0,O:0,neutral:0};for(const c of b)if(c!==".")area[c]++;for(const r of regions)if(r.boundary.length===1)area[r.boundary[0]]+=r.points.length;else area.neutral+=r.points.length;return {board:b,groups,regions,area}}

function verify(log){
 const parse=inspect;
 const adj=i=>[i%9?i-1:-1,i%9<8?i+1:-1,i>=9?i-9:-1,i<72?i+9:-1].filter(j=>j>=0);
 const point=s=>(9-Number(s.slice(1)))*9+"ABCDEFGHJ".indexOf(s[0]);
 const name=i=>"ABCDEFGHJ"[i%9]+(9-Math.floor(i/9));
 const board=Array(81).fill("."),moves=[],captures={X:0,O:0},events=[],checks=[];let ko=null;
 const group=i=>{const todo=[i],seen=new Set([i]),libs=new Set();while(todo.length){for(const j of adj(todo.pop()))if(board[j]===".")libs.add(j);else if(board[j]===board[i]&&!seen.has(j)){seen.add(j);todo.push(j)}}return{stones:[...seen],libs:[...libs]}};
 function play(color,move){const n=moves.length+1;if(move==="pass"){ko=null;moves.push({number:n,color,move});return}const i=point(move);if(board[i]!=="."||i===ko)throw Error("occupied or ko at "+n);board[i]=color;const removed=[];for(const j of adj(i))if(board[j]!=="."&&board[j]!==color){const g=group(j);if(!g.libs.length){for(const k of g.stones){removed.push(k);board[k]="."}}}const own=group(i);if(!own.libs.length)throw Error("suicide at "+n);captures[color]+=removed.length;ko=removed.length===1&&own.stones.length===1&&own.libs.length===1?removed[0]:null;moves.push({number:n,color,move});if(removed.length)events.push({number:n,color,move,captured:removed.map(name).sort()});}
 for(const [index,s] of log.snapshots.entries()){
  const t=s.raw.content.filter(c=>c.type==="text").map(c=>c.text).join("\n");
  if(s.kind==="play"){play("X",s.move);const m=t.match(/Your opponent played ([A-HJ][1-9])\./);if(m)play("O",m[1]);else if(/Your opponent passed\./.test(t))play("O","pass");else throw Error("missing opponent at "+index);}
  const actual=parse(s.raw);if(actual.board.join("")!==board.join(""))throw Error("board mismatch "+index);
  const c=t.match(/Captured by Black: (\d+); by White: (\d+)\./);if(!c||+c[1]!==captures.X||+c[2]!==captures.O)throw Error("capture mismatch "+index);
  const n=t.match(/Move number: (\d+)\./);if(!n||+n[1]!==moves.length+1)throw Error("move number mismatch "+index);
  const k=t.match(/Ko point: (none|[A-HJ][1-9])\./);if(!k||k[1]!== (ko===null?"none":name(ko)))throw Error("ko mismatch "+index);
  checks.push({snapshot:index,kind:s.kind,afterMove:moves.length,board:true,captures:true,nextMove:true,ko:true});
 }
 return{game:131,moves,snapshots:checks.length,checks,captureEvents:events,physicalCaptures:captures,final:parse(log.snapshots.at(-1).raw)};
}

